examples.template:
HStack(alignment: .top, spacing: 8) {
    MonarchPhoneCountrySelect(
        {{countryLabel}},
        selection: $country,
        preferred: [{{preferred.0}}, {{preferred.1}}]
    )
    .fixedSize(horizontal: true, vertical: false)
    .onChange(of: country) { _, code in
        dialCode = code.flatMap { MonarchPhoneCountry.country(code: $0)?.dialCode }
    }
    MonarchTextField(
        {{phoneLabel}},
        text: $number,
        helper: {{savedAs}} + " " + (dialCode ?? "—") + " " + (number.isEmpty ? {{numberPlaceholder}} : number)
    )
}

examples.setupTemplate:
@State private var country: String? = {{country}}
@State private var dialCode: String? = {{dialCode}}
@State private var number = {{number}}

examples.setup:
@State private var country: String? = "GB"
@State private var dialCode: String? = "+44"
@State private var number = ""

examples.code:
HStack(alignment: .top, spacing: 8) {
    MonarchPhoneCountrySelect(
        "Country code",
        selection: $country,
        preferred: ["GB", "US"]
    )
    .fixedSize(horizontal: true, vertical: false)
    .onChange(of: country) { _, code in
        dialCode = code.flatMap { MonarchPhoneCountry.country(code: $0)?.dialCode }
    }
    MonarchTextField(
        "Phone number",
        text: $number,
        helper: "Saved as" + " " + (dialCode ?? "—") + " " + (number.isEmpty ? "…" : number)
    )
}
